How about a solution for primes below a number using Sieve of Eratosthenes:<p><pre><code>  template<int H=-1, typename T=void>
  struct tl {
      enum {head=H};
      typedef T tail;
  };

  template<>
  struct tl<> {
  };

  template<int N, typename Then, typename Else>
  struct if_c {
      typedef Then type;
  };

  template<typename Then, typename Else>
  struct if_c<false, Then, Else> {
      typedef Else type;
  };

  template<int N, typename SoFar>
  struct is_prime {
      enum {value = N%SoFar::head && is_prime<N, SoFar::tail>::value};
  };

  template<int N>
  struct is_prime<N, tl<>> {
      enum {value = 1};
  };

  template<int N, int C, typename SoFar=tl<>>
  struct prime {
      typedef typename prime<N+1, C-1, typename if_c<is_prime<N, SoFar>::value, tl<N, SoFar>, SoFar>::type>::type type;
  };

  template<int N, typename SoFar>
  struct prime<N, 0, SoFar> {
      typedef SoFar type;
  };

  template<int N>
  struct number : prime<2, N-2> {
  };

  template<>
  struct number<0> {
  };

  template<>
  struct number<1> {
  };

  template<typename T>
  struct print {
  };

  void main() {
      typedef print<number<300>::type>::type type;
  }

</code></pre>
